static void dump(const char *tag, const hmi_app_cfg_t *c, bool ok, const char *err)
{
    printf("%s ok=%d err='%s'\n", tag, ok ? 1 : 0, err);
    printf("  host='%s' port=%u unit=%u rto=%u cto=%u writes=%d n=%zu\n", c->host, c->port, c->unit,
           c->response_timeout_ms, c->connect_timeout_ms, c->writes_enabled ? 1 : 0, c->n_tags);
    for (size_t i = 0; i < c->n_tags; i++) {
        const hmi_tag_cfg_t *t = &c->tags[i];
        printf("  tag[%zu] name='%s' units='%s' area=%d addr=%u dt=%d wo=%d bo=%d scale=%.17g off=%.17g "
               "emin=%.17g emax=%.17g poll=%u\n",
               i, t->name, t->units, (int)t->area, t->address, (int)t->dtype, (int)t->word_order,
               (int)t->byte_order, t->scale, t->offset, t->eng_min, t->eng_max, t->poll_ms);
        printf("    alarm en=%d%d%d%d hi=%.17g hihi=%.17g lo=%.17g lolo=%.17g db=%.17g on=%u off=%u\n",
               t->alarm.en_hi, t->alarm.en_hihi, t->alarm.en_lo, t->alarm.en_lolo, t->alarm.hi,
               t->alarm.hihi, t->alarm.lo, t->alarm.lolo, t->alarm.deadband, t->alarm.on_ms,
               t->alarm.off_ms);
        printf("    write allowed=%d role=%d min=%.17g max=%.17g\n", t->write_allowed ? 1 : 0,
               (int)t->write_role, t->write_min, t->write_max);
    }
}

static void run(const char *tag, const char *json, size_t len)
{
    static hmi_app_cfg_t c;
    char err[160];
    memset(&c, 0xA5, sizeof(c)); /* a parser must not depend on caller contents */
    err[0] = '\0';
    bool ok = hmi_config_parse(json, len, &c, err, sizeof(err));
    dump(tag, &c, ok, err);
}

int main(void)
{
#ifdef _WIN32
    _setmode(_fileno(stdout), _O_BINARY); /* identical bytes on every platform */
#endif
    char buf[HMI_CONFIG_MAX_BYTES + 64];
    size_t nm = sizeof(MUTS) / sizeof(MUTS[0]);
    for (size_t i = 0; i < nm; i++) {
        const char *p = MUTS[i].from[0] ? strstr(BASE, MUTS[i].from) : BASE;
        char tag[32];
        snprintf(tag, sizeof(tag), "case %03zu", i);
        if (!p) {
            printf("%s PATTERN NOT FOUND\n", tag);
            continue;
        }
        size_t pre = (size_t)(p - BASE), flen = strlen(MUTS[i].from);
        int n = snprintf(buf, sizeof(buf), "%.*s%s%s", (int)pre, BASE, MUTS[i].to, p + flen);
        run(tag, buf, (size_t)n);
    }
    /* whole-document cases */
    run("doc empty", "", 0);
    run("doc NULL-len0", NULL, 0);
    run("doc garbage", "not json", 8);
    run("doc array", "[]", 2);
    run("doc string", "\"x\"", 3);
    run("doc nested-empty", "{}", 2);
    run("doc truncated", BASE, strlen(BASE) / 2);
    /* size limits */
    memset(buf, ' ', sizeof(buf));
    memcpy(buf, BASE, strlen(BASE));
    run("doc exactly-max", buf, HMI_CONFIG_MAX_BYTES);
    run("doc over-max", buf, HMI_CONFIG_MAX_BYTES + 1);
    /* 64 and 65 tags (tag count limit), distinct names, 1 register each */
    for (int count = 64; count <= 65; count++) {
        size_t off = (size_t)snprintf(buf, sizeof(buf),
            "{\"version\":1,\"plc\":{\"host\":\"10.0.0.1\",\"port\":502,\"unit\":1},\"tags\":[");
        for (int k = 0; k < count; k++) {
            off += (size_t)snprintf(buf + off, sizeof(buf) - off,
                "%s{\"name\":\"T%d\",\"address\":%d,\"type\":\"u16\"}", k ? "," : "", k, k * 3);
        }
        off += (size_t)snprintf(buf + off, sizeof(buf) - off, "]}");
        char tag[32];
        snprintf(tag, sizeof(tag), "doc tags-%d", count);
        run(tag, buf, off);
    }
    /* token budget: 60 tags x 8 keys exceeds 1024 jsmn tokens within 32 KB */
    {
        size_t off = (size_t)snprintf(buf, sizeof(buf),
            "{\"version\":1,\"plc\":{\"host\":\"10.0.0.1\",\"port\":502,\"unit\":1},\"tags\":[");
        for (int k = 0; k < 60; k++) {
            off += (size_t)snprintf(buf + off, sizeof(buf) - off,
                "%s{\"name\":\"T%d\",\"address\":%d,\"type\":\"u16\",\"scale\":1,\"offset\":0,"
                "\"min\":0,\"max\":9,\"poll_ms\":1000}", k ? "," : "", k, k * 3);
        }
        off += (size_t)snprintf(buf + off, sizeof(buf) - off, "]}");
        run("doc tokens-60x8", buf, off);
    }
    return 0;
}
